// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {XBORNID} from "../src/XBORNID.sol";

contract InvMutTest is Test {
    XBORNID c;
    function setUp() public { c = new XBORNID(); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(c.blacklist(actor) == false);

        // drive c through the public distribution entry point
        vm.prank(actor);
        c.getTokens();

        // General rule: distribution only ever moves amount from totalRemaining
        // into totalDistributed, so their sum stays equal to totalSupply.
        assertTrue(c.totalRemaining() + c.totalDistributed() == c.totalSupply());
    }
}
